### Tier 2: Essential Defenses (15 min)

**Add key rotation and HSM integration**

```java
// SECURE: Key rotation with multiple active keys
package com.example.security;

import org.springframework.stereotype.Service;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class KeyRotationService {

    private final Map<String, SecretKey> activeKeys = new ConcurrentHashMap<>();
    private String currentKeyId;

    public String encrypt(String data) throws Exception {
        // ✅ Tag ciphertext with key ID for rotation
        String keyId = currentKeyId;
        SecretKey key = activeKeys.get(keyId);

        // ... encrypt with current key ...
        String ciphertext = encryptWithKey(data, key);

        // Prepend key ID for decryption
        return keyId + ":" + ciphertext;
    }

    public String decrypt(String encryptedData) throws Exception {
        // ✅ Extract key ID and decrypt with appropriate key
        String[] parts = encryptedData.split(":", 2);
        String keyId = parts[0];
        String ciphertext = parts[1];

        SecretKey key = activeKeys.get(keyId);
        if (key == null) {
            throw new SecurityException("Key not found: " + keyId);
        }

        return decryptWithKey(ciphertext, key);
    }

    // ✅ Rotate keys without downtime
    public void rotateKey(String newKeyId, SecretKey newKey) {
        activeKeys.put(newKeyId, newKey);
        currentKeyId = newKeyId;

        // Keep old keys active for 30 days (decrypt legacy data)
        scheduleKeyRemoval(newKeyId, 30);
    }
}

// SecurityConfig for audit logging
@Configuration
public class CryptoSecurityConfig {

    @Bean
    public FilterRegistrationBean<CryptoAuditFilter> cryptoAudit() {
        FilterRegistrationBean<CryptoAuditFilter> registration = new FilterRegistrationBean<>();
        registration.setFilter(new CryptoAuditFilter());
        registration.addUrlPatterns("/api/*");
        return registration;
    }
}

class CryptoAuditFilter implements Filter {
    private static final Logger log = LoggerFactory.getLogger(CryptoAuditFilter.class);

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {

        // ✅ Log all encryption/decryption operations
        HttpServletRequest httpRequest = (HttpServletRequest) request;
        String operation = httpRequest.getParameter("operation");

        if ("encrypt".equals(operation) || "decrypt".equals(operation)) {
            log.info("Crypto operation: {} from IP: {}",
                operation,
                httpRequest.getRemoteAddr());
        }

        chain.doFilter(request, response);
    }
}
```

### Tier 3: Production Hardening (30 min)

**Add monitoring, testing, and key management**

```java
// SECURE: Comprehensive monitoring
package com.example.security;

import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;
import org.springframework.stereotype.Component;

@Component
public class CryptoMonitor {

    private final Counter encryptionCounter;
    private final Counter decryptionCounter;
    private final Counter encryptionFailures;
    private final Timer encryptionDuration;

    public CryptoMonitor(MeterRegistry registry) {
        this.encryptionCounter = Counter.builder("crypto.encryption.total")
            .description("Total encryption operations")
            .register(registry);

        this.decryptionCounter = Counter.builder("crypto.decryption.total")
            .description("Total decryption operations")
            .register(registry);

        this.encryptionFailures = Counter.builder("crypto.failures")
            .description("Cryptographic operation failures")
            .tag("severity", "critical")
            .register(registry);

        this.encryptionDuration = Timer.builder("crypto.operation.duration")
            .description("Encryption operation duration")
            .register(registry);
    }

    public void recordEncryption() {
        encryptionCounter.increment();
    }

    public void recordDecryption() {
        decryptionCounter.increment();
    }

    public void recordFailure() {
        encryptionFailures.increment();
    }

    public Timer.Sample startTimer() {
        return Timer.start();
    }

    public void recordDuration(Timer.Sample sample) {
        sample.stop(encryptionDuration);
    }
}

// Integration tests
@SpringBootTest
@AutoConfigureMockMvc
public class CryptoSecurityTest {

    @Autowired
    private SecureCryptoService cryptoService;

    @Test
    public void testEncryptionDecryption() throws Exception {
        String plaintext = "Sensitive data 12345";

        String ciphertext = cryptoService.encrypt(plaintext);
        String decrypted = cryptoService.decrypt(ciphertext);

        assertEquals(plaintext, decrypted);
    }

    @Test
    public void testDifferentIVs() throws Exception {
        // ✅ Verify each encryption produces different ciphertext
        String plaintext = "Same data";

        String ciphertext1 = cryptoService.encrypt(plaintext);
        String ciphertext2 = cryptoService.encrypt(plaintext);

        assertNotEquals(ciphertext1, ciphertext2,
            "Same plaintext should produce different ciphertext (random IVs)");
    }

    @Test
    public void testWeakAlgorithmRejected() {
        // ✅ Verify DES/3DES rejected
        assertThrows(NoSuchAlgorithmException.class, () -> {
            Cipher.getInstance("DES");
        });
    }

    @Test
    public void testKeyNotHardcoded() {
        // ✅ Verify no hardcoded keys in bytecode
        byte[] classBytes = SecureCryptoService.class
            .getResourceAsStream("SecureCryptoService.class")
            .readAllBytes();

        String bytecode = new String(classBytes);
        assertFalse(bytecode.contains("MySecretKey"),
            "Hardcoded keys must not exist in bytecode");
    }
}

